/**
 * Loads the build-time translation file for a locale.
 *
 * The files under `public/_gt/` are generated by the `gt` CLI
 * (`npx gt generate` for empty templates, `npx gt translate` for real
 * translations) and are gitignored. Until they exist, this resolves to `{}`
 * and the app renders in the source locale.
 */
export default async function loadTranslations(locale: string) {
  try {
    const translations = await import(`../public/_gt/${locale}.json`);
    return translations.default;
  } catch {
    return {};
  }
}
